const assert = require('node:assert/strict');
const { Given, When, Then } = require('@cucumber/cucumber');
const { STORAGE_KEY } = require('./world');

const KEY_CODES = { Enter: 13, Escape: 27 };

function press(world, element, key) {
  for (const type of ['keydown', 'keyup']) {
    const event = new world.window.KeyboardEvent(type, { key, bubbles: true, cancelable: true });
    Object.defineProperty(event, 'keyCode', { get: () => KEY_CODES[key] });
    Object.defineProperty(event, 'which', { get: () => KEY_CODES[key] });
    element.dispatchEvent(event);
  }
}

function fire(world, element, type) {
  element.dispatchEvent(new world.window.Event(type, { bubbles: true, cancelable: true }));
}

function click(world, element) {
  element.dispatchEvent(new world.window.MouseEvent('click', { bubbles: true, cancelable: true }));
}

function isHidden(world, element) {
  if (!element) return true;
  if (element.hidden) return true;
  const inline = (element.getAttribute('style') || '').replace(/\s/g, '');
  if (inline.includes('display:none')) return true;
  if (element.classList.contains('hidden')) return true;
  const computed = world.window.getComputedStyle(element);
  return computed ? computed.display === 'none' : false;
}

function visibleItems(world) {
  return Array.from(world.document.querySelectorAll('.todo-list li')).filter((li) => !isHidden(world, li));
}

function titleOf(item) {
  const label = item.querySelector('label');
  return label ? label.textContent.trim() : '';
}

function shownTitles(world) {
  return visibleItems(world).map(titleOf);
}

function expectedTitles(list) {
  return list
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

function itemFor(world, title) {
  const item = visibleItems(world).find((li) => titleOf(li) === title);
  assert.ok(item, `no todo titled "${title}" is shown; shown: ${JSON.stringify(shownTitles(world))}`);
  return item;
}

function newTodoInput(world) {
  const input = world.document.querySelector('.new-todo');
  assert.ok(input, 'the page has no ".new-todo" input');
  return input;
}

function beginEdit(world, title) {
  const item = itemFor(world, title);
  const label = item.querySelector('label');
  label.dispatchEvent(new world.window.MouseEvent('dblclick', { bubbles: true, cancelable: true }));
}

function editInput(world, title) {
  const item = Array.from(world.document.querySelectorAll('.todo-list li')).find(
    (li) => titleOf(li) === title || li.classList.contains('editing'),
  );
  assert.ok(item, `no todo item found for "${title}"`);
  const input = item.querySelector('.edit');
  assert.ok(input, `the todo "${title}" has no ".edit" input`);
  return input;
}

function storedTodos(world) {
  const raw = world.localStorage.getItem(STORAGE_KEY);
  if (raw === null || raw === undefined) return [];
  return JSON.parse(raw);
}

function normalize(text) {
  return text.replace(/\s+/g, ' ').trim();
}

Given('the app is loaded with no saved todos', function () {
  assert.equal(storedTodos(this).length, 0, 'expected no saved todos at start');
});

Given('the app is loaded with the todos:', async function (table) {
  const todos = table.hashes().map((row, index) => ({
    id: `seed-${index + 1}`,
    title: row.title,
    completed: row.completed === 'true',
  }));
  await this.seedStorage(JSON.stringify(todos));
  assert.deepEqual(
    shownTitles(this),
    todos.map((todo) => todo.title),
    'the seeded todos did not render',
  );
});

When('the user adds the todo {string}', function (title) {
  const input = newTodoInput(this);
  input.value = title;
  fire(this, input, 'input');
  press(this, input, 'Enter');
});

When('the user toggles the todo {string}', function (title) {
  const toggle = itemFor(this, title).querySelector('.toggle');
  assert.ok(toggle, `the todo "${title}" has no ".toggle" checkbox`);
  toggle.checked = !toggle.checked;
  fire(this, toggle, 'change');
});

When('the user double-clicks the label of the todo {string}', function (title) {
  beginEdit(this, title);
});

When('the user clicks the remove button of the todo {string}', function (title) {
  const button = itemFor(this, title).querySelector('.destroy');
  assert.ok(button, `the todo "${title}" has no ".destroy" button`);
  click(this, button);
});

When('the user clicks the mark all as complete checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(toggleAll, 'the page has no ".toggle-all" checkbox');
  toggleAll.checked = !toggleAll.checked;
  fire(this, toggleAll, 'change');
});

When('the user clicks the clear completed button', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page has no ".clear-completed" button');
  click(this, button);
});

When('the user edits the todo {string} to {string} and presses Enter', function (title, next) {
  beginEdit(this, title);
  const input = editInput(this, title);
  input.value = next;
  fire(this, input, 'input');
  press(this, input, 'Enter');
});

When('the user edits the todo {string} to {string} and blurs the input', function (title, next) {
  beginEdit(this, title);
  const input = editInput(this, title);
  input.value = next;
  fire(this, input, 'input');
  fire(this, input, 'blur');
});

When('the user edits the todo {string} to {string} and presses Escape', function (title, next) {
  beginEdit(this, title);
  const input = editInput(this, title);
  input.value = next;
  fire(this, input, 'input');
  press(this, input, 'Escape');
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the user clicks the filter link {string}', function (name) {
  const link = Array.from(this.document.querySelectorAll('.filters a')).find(
    (anchor) => anchor.textContent.trim() === name,
  );
  assert.ok(link, `no filter link named "${name}"`);
  click(this, link);
});

When('the user reloads the app', async function () {
  await this.reloadApp();
});

Then('the {string} section is hidden', function (name) {
  const section = this.document.querySelector(`.${name}`);
  assert.ok(isHidden(this, section), `the "${name}" section is visible`);
});

Then('the {string} section is visible', function (name) {
  const section = this.document.querySelector(`.${name}`);
  assert.ok(section, `the page has no ".${name}" section`);
  assert.ok(!isHidden(this, section), `the "${name}" section is hidden`);
});

Then('the todo list shows the titles {string}', function (list) {
  assert.deepEqual(shownTitles(this), expectedTitles(list));
});

Then('the todo list is empty', function () {
  assert.deepEqual(shownTitles(this), []);
});

Then('the new todo input is empty', function () {
  assert.equal(newTodoInput(this).value, '');
});

Then('the new todo input has the {string} attribute', function (name) {
  assert.ok(newTodoInput(this).hasAttribute(name), `the new todo input has no "${name}" attribute`);
});

Then('the todo {string} is completed', function (title) {
  const toggle = itemFor(this, title).querySelector('.toggle');
  assert.equal(toggle.checked, true, `the todo "${title}" is not completed`);
});

Then('the todo {string} is active', function (title) {
  const toggle = itemFor(this, title).querySelector('.toggle');
  assert.equal(toggle.checked, false, `the todo "${title}" is not active`);
});

Then('the todo {string} list item has the class {string}', function (title, className) {
  assert.ok(
    itemFor(this, title).classList.contains(className),
    `the todo "${title}" list item lacks the class "${className}"`,
  );
});

Then('the todo {string} list item does not have the class {string}', function (title, className) {
  assert.ok(
    !itemFor(this, title).classList.contains(className),
    `the todo "${title}" list item carries the class "${className}"`,
  );
});

Then('the toggle of the todo {string} is checked', function (title) {
  assert.equal(itemFor(this, title).querySelector('.toggle').checked, true);
});

Then('the todo {string} has a remove button', function (title) {
  assert.ok(itemFor(this, title).querySelector('.destroy'), `the todo "${title}" has no remove button`);
});

Then('every todo is completed', function () {
  const items = visibleItems(this);
  assert.ok(items.length > 0, 'no todos are shown');
  for (const item of items)
    assert.equal(item.querySelector('.toggle').checked, true, `"${titleOf(item)}" is not completed`);
});

Then('every todo is active', function () {
  const items = visibleItems(this);
  assert.ok(items.length > 0, 'no todos are shown');
  for (const item of items)
    assert.equal(item.querySelector('.toggle').checked, false, `"${titleOf(item)}" is not active`);
});

Then('the mark all as complete checkbox is checked', function () {
  assert.equal(this.document.querySelector('.toggle-all').checked, true);
});

Then('the mark all as complete checkbox is unchecked', function () {
  assert.equal(this.document.querySelector('.toggle-all').checked, false);
});

Then('the counter reads {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.ok(counter, 'the page has no ".todo-count" element');
  assert.equal(normalize(counter.textContent), text);
});

Then('the counter strong tag reads {string}', function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'the counter has no "strong" element');
  assert.equal(normalize(strong.textContent), text);
});

Then('the clear completed button is hidden', function () {
  assert.ok(isHidden(this, this.document.querySelector('.clear-completed')), 'the clear completed button is visible');
});

Then('the clear completed button is visible', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page has no ".clear-completed" button');
  assert.ok(!isHidden(this, button), 'the clear completed button is hidden');
});

Then('the edit input of the todo {string} holds {string}', function (title, value) {
